INSERT INTO projects (id, title, description, long_description, icon, tags, details, links, is_featured, status, position) VALUES ('pitchforks', 'Pitchforks & Paragraphs', 'A fast-paced medieval typing game where you cast word-spells to quell peasant riots. Built from scratch in Unity.', '<p>Pitchforks & Paragraphs is a wave-based typing game where players must type words displayed on peasants'' signs to cast spells and disperse them. The game features a dynamic difficulty system, a combo-based scoring mechanism that rewards speed and accuracy, and online leaderboards.</p>', 'gamepad-2', '["Unity","C#","Blender","MagicaVoxel"]', '[{"label":"Platform","value":"Web"},{"label":"Type","value":"Game"}]', '[{"label":"Play on itch.io","url":"https://dustylv.itch.io/pitchforksnparagraphs"}]', 1, 'published', 0);
