INSERT INTO projects (id, title, description, long_description, icon, tags, details, links, is_featured, status, position) VALUES ('lipke-guide', 'Žanis Lipke Memorial Digital Guide', 'A digital guide to enhance the memorial experience.', '<p>Creation of digital guide to run on an Android tablet. It provides additional information to the physical exhibits inside the memorial - like a real-life guide would.
        <br><br>
        It gives insights for each exhibit with images, text and videos. To improve the user experience, Bluetooth beacons we''re added to automatically switch to the nearest exhibit and show its content.<br>
        To improve this applications longevity, a custom content management system (CMS) was created that the memorial employees or curators can edit and add new content.
        <br><br>
        An outdoors mode was created to give visitors a guided tour - a custom route was created that takes them around the memorial area to see various points of interest. In these points, contextual information is given, as well as some Augmented Reality (AR) elements
        are added to some points.
        Visitors are guided with a top-down map of the area, like any other navigation, with the POIs marked on the map.
        <br><br>
        Since these Android tablets would not have internet connection outside, the navigation was made from the ground-up. An offline map tiling system and a navigation line drawing system were created.
        </p>', 'landmark', '["Unity","C#","AR","Android","Google Services"]', '[{"label":"Platform","value":"Mobile (Android)"},{"label":"Type","value":"EdTech"}]', '[{"label":"Lipke memorial","url":"https://lipke.lv/en/"}]', 0, 'published', 1);
INSERT INTO projects (id, title, description, long_description, icon, tags, details, links, is_featured, status, position) VALUES ('rix', 'RIX Airport Digital Twin 3D Model', 'Creation of Riga (RIX) airport 3D model.', '<p>Creation of 3D model for RIX airport runways and surrounding territory. Modeled and textured the terrain, signage and other necessary objects, as well as buildings.
        <br><br>
        The model needed to be as performant as possible, so custom shaders were created for terrain texturing, to use Vertex Colors for masking. As well as, creation and use of texture atlases for signage, ground lines, etc.
        </p>', 'plane', '["Blender","Unity","Amplify Shader"]', '[{"label":"Platform","value":"VR Standalone"},{"label":"Type","value":"3D Model"}]', '[]', 0, 'published', 2);
INSERT INTO projects (id, title, description, long_description, icon, tags, details, links, is_featured, status, position) VALUES ('lipke-vr', 'Žanis Lipke Memorial VR Experience', 'A VR experience for the Žanis Lipke Memorial museum, allowing virtual exploration of the hideout used to save Jews in WWII.', '<p>This VR application virtually recreates the woodsman''s hut and the underground bunker where Žanis Lipke hid people during WWII. The experience allows users to explore the historical site and is used in the museum for educational purposes.</p>', 'landmark', '["Unity","C#","VR","Blender"]', '[{"label":"Platform","value":"VR Standalone"},{"label":"Type","value":"Museum Exhibit"}]', '[{"label":"Lipke memorial","url":"https://lipke.lv/en/"}]', 0, 'published', 3);
