INSERT INTO projects (id, title, description, long_description, icon, tags, details, links, is_featured, status, position) VALUES ('volga-heatwave', 'Volga Heatwave', 'A hobby game about a dog trapped in a hot car who must attract attention to be saved before the temperature gets too high.', '<p>Volga Heatwave is a game about a dog trapped in a hot car who must attract the attention of passersby to be saved. The player''s goal is to fill an "attention meter" by interacting with objects in the car, which makes a crowd gather outside. All the while, a temperature meter is constantly rising, and if it reaches its maximum value, the game is over. 
        <br><br>
        This was a solo project where I handled all development and art aspects.
        This was made for the Unity development course while attending masters studies in Vidzeme University.
        Afterwards, I polished the game and submitted it to the Latvian Gamedev association organized game jam/competition ''BRSD 12'' (Beidz runāt, sāc darīt | Stop talking, start doing). Came in 7th out of 15 submissions.
        </p>', 'dog', '["Unity","Blender"]', '[{"label":"Platform","value":"PC"},{"label":"Type","value":"Game"}]', '[{"label":"Play on itch.io","url":"https://dustylv.itch.io/volga-heatwave"}]', 0, 'published', 4);
