INSERT INTO projects (id, title, description, long_description, icon, tags, details, links, is_featured, status, position) VALUES ('crayfish-rush', 'Crayfish Rush', 'A VR experience where the player has to catch crayfish in a river.', '<p>This is a VR game for Ape museum in Latvia. The games purpose is to allow players to immerse themselves in an activity that''s becoming quite rare - catching crayfish in a river. </p><br>
      <p>The player must catch as many crayfish as possible in the given time. They are presented with 3 crayfish traps in the river next to them and they must wait for the crayfish to go into them. When that happens, the player pulls up the trap and takes the crayfish and places it into the bag that''s around their neck. <br>
      This process is repeated until the end of the game. The amount of crayfish in the bag is counted at the end of the game and shown on the scoreboard. Players can compete for the highest score.</p>', 'crab', '["Unity","C#"]', '[{"label":"Platform","value":"VR Standalone"},{"label":"Type","value":"Edutainment"}]', '[]', 0, 'published', 5);
