INSERT INTO projects (id, title, description, long_description, icon, tags, details, links, is_featured, status, position) VALUES ('izlidzi-vitolam', 'Izlīdzi vītolam', 'A Virtual Reality choir conducting game with gesture recognition.', '<p>A Virtual Reality choir conducting game with gesture recognition. <br><br> The game serves as an interactive experience to see what a choir conductor does. The player has to perform various patterns with arm movements that correspond with what an actual conductor would make to give instructions to the choir.</p>', 'heart-handshake', '["Unity","C#"]', '[{"label":"Platform","value":"PC VR"},{"label":"Type","value":"Edutainment"}]', '[]', 0, 'published', 6);
