INSERT INTO projects (id, title, description, long_description, icon, tags, details, links, is_featured, status, position) VALUES ('zaao', 'ZAAO VR Sorting Game', 'A VR game for a waste management company (ZAAO) to educate players on proper waste sorting in an interactive way.', '<p>This educational VR game gamifies the process of waste sorting. Players are placed in a virtual environment where they must correctly sort different types of trash into the appropriate bins under a time limit.</p><br>
      <p>The main challenge was the use of a 360° image for the background and 3D models for the interactable objects. This choice was made so that the game looks realistic. Creating the environment as a 3D model was not feasible as the game was supposed to run on an Oculus Go headset, and does not have the horsepower to process that much.</p>', 'recycle', '["Unity","C#","VR","Blender"]', '[{"label":"Platform","value":"Standalone VR"},{"label":"Type","value":"Edutainment"}]', '[]', 0, 'published', 7);
