INSERT INTO projects (id, title, description, long_description, icon, tags, details, links, is_featured, status, position) VALUES ('train-dispatch', 'Train Dispatcher Game', 'A train dispatch edutainment game for Gulbene train museum. ', '<p>Allows the player to take on the role of a train dispatch and make decisions to divert trains to the correct rails. Gives an insight on what a train dispatch actually does. <br><br>
The player is given a description of the situation and they must choose an appropriate course of action from the given choices. </p>', 'train', '["Unity","C#"]', '[{"label":"Platform","value":"PC"},{"label":"Type","value":"Edutainment"}]', '[]', 0, 'published', 8);
