INSERT INTO projects (id, title, description, long_description, icon, tags, details, links, is_featured, status, position) VALUES ('art-plus', 'Art+', 'Various 3D models for ART+ AR application viewable in multiple places across Latvia', '<p>ART+ is a collaborative artist effort of bringing art experiences to AR. In different places in Liepaja, Kuldiga and Valmiera, people can use their phones or tablets to view and experience various art and other significant objects.
<br><br>
You can check it out here: https://artplus.app/
<br><br>
My part in this was to create a few 3D models and add some effects to some of them:
<br>
    <ul>
    <li> - Airplane "KOD" or "Ventas Eagle"</li>
    <li> - Roots</li>
    <li> - The white clover</li>
    <li> - Libau - Romny Railway</li>
    </ul>
</p>', 'image-plus', '["Blender","AR","Unity"]', '[{"label":"Platform","value":"Augmented Reality"},{"label":"Type","value":"3D Model"}]', '[]', 0, 'published', 9);
