INSERT INTO projects (id, title, description, long_description, icon, tags, details, links, is_featured, status, position) VALUES ('audio-viz', 'Audio Visualizations', 'Hobby audio vizualization renders.', '<p>These are some personal hobby projects where I wanted to create an animation with audio, where objects in the scene would react to audio. Both projects are for already songs, not original tracks.
      <br>
      </p>', 'bar-chart-3', '["Blender"]', '[{"label":"Platform","value":"Video"},{"label":"Type","value":"3D Model"}]', '[]', 0, 'published', 10);
