INSERT INTO projects (id, title, description, long_description, icon, tags, details, links, is_featured, status, position) VALUES ('bog-sim', 'Bog Simulator', 'An automated generation of digital twin in virtual reality for interaction with specific nature ecosystem.', '<p>This scientific project was aimed towards creating a VR experience to visualize realtime simulation data in an easier form. The simulation was made for a bog ecosystem and as the main parameter to be simulated was underground water level. <br><br>
      This water level is impacted by various factors, but one of the goals for this visualization was how human actions impact the ecosystem. And to demonstrate it, tree cutting was chosen as the main action. If the user cuts down a tree, the simulation is run and the water level data is updated.
<br><br>
This project incorporates GIS data to create the virtual terrain and various drone LIDAR datasets used to place vegetation.</p>', 'leaf', '["Unity","VR","Blender"]', '[{"label":"Platform","value":"PC VR"},{"label":"Type","value":"Simulation"}]', '[]', 0, 'published', 11);
INSERT INTO projects (id, title, description, long_description, icon, tags, details, links, is_featured, status, position) VALUES ('motor-assembly', 'Motor Assembly VR', 'A VR learning environment for teaching the step-by-step process of assembling a complex electric motor.', '<p>This technical training application guides users through the intricate process of motor assembly. It features interactive parts, instructional overlays, and performance feedback to ensure effective learning.
      <br><br>
      The applications purpose is to allow university students to learn mechatronics in a virtual environment. 
Main idea is to allow to learn how to assemble and operate various mechanical devices.
<br><br>
This training application has less focus on safety, but more on the different levels of depth a training environment can have. 
<br>
In this project, also a grading system was implemented that allows to gain more insights on how well does the student understands the subject and where they might need to improve.
<br><br>
As an example, an electric motor was chosen. The application has three levels of complexity.</p>', 'cog', '["Unity","VR","C#","Blender"]', '[{"label":"Platform","value":"Standalone VR"},{"label":"Type","value":"Training"}]', '[]', 0, 'published', 12);
