INSERT INTO projects (id, title, description, long_description, icon, tags, details, links, is_featured, status, position) VALUES ('safescaff', 'SafeScaff VR', 'A VR safety training simulation for construction workers, focusing on the correct and safe procedures for erecting scaffolding.', '<p>SafeScaff provides a hands-on, risk-free environment for workers to learn and be tested on scaffolding safety protocols, helping to reduce workplace accidents.
      <br><br>
      The users have the task of building a scaffolding structure while performing all safety measures. This includes wearing all the necessary safety equipment, constructing the scaffolding in the correct order, securing all scaffolding pieces so that they don''t move.
<br><br>
The whole process and the users actions are recorded. They are used afterwards to determine if the user did everything correctly or what mistakes were made. That allows for a deeper learning process that helps users to learn faster and safer.
<br><br>
This project supports both singleplayer and multiplayer modes.</p>', 'construction', '["Unity","VR","C#","Blender"]', '[{"label":"Platform","value":"Standalone VR"},{"label":"Type","value":"Training"}]', '[]', 0, 'published', 13);
INSERT INTO projects (id, title, description, long_description, icon, tags, details, links, is_featured, status, position) VALUES ('exonicus', 'XR Prototype for Exonicus Inc.', 'Freelance job for Exonicus Inc. to create a prototype for ArUco marker tracking.', '<p>The main idea of the prototype was to test how well the Vive XR Elite headset performs with tracking ArUco markers and if it would be suitable to use.
<br><br>
By using the headset passthrough and ability to detect and track markers in real-time, digital objects would be attached to each marker and follow it.
<br><br>
This was done in Unity, using the Vive Wave SDK packages, which provide ArUco marker tracking support. At the time of development the tracking performance was awful and not suitable for smooth real-time operation.
<br><br>
This was a solo project where I developed and implemented all of the logic based on the provided specifications.</p>', 'activity', '["Unity","XR","C#"]', '[{"label":"Platform","value":"Standalone VR"},{"label":"Type","value":"Prototyping"}]', '[]', 0, 'published', 14);
INSERT INTO projects (id, title, description, long_description, icon, tags, details, links, is_featured, status, position) VALUES ('overly', 'Exposition app for OverlyApp', 'Freelance job for OverlyApp to create an exposition application.', '<p>An exposition app for Ventspils science centre. The app allows users to view online webcams showing wild animals such as eagle or stork nests. The app also has a wide library of animals, birds and sea creatures found in Latvia.
<br><br>
The app was made in Unity with its UI components to display necessary information.
<br><br>
It is a static app where the exposition information is mostly static - for this reason a simple Excel spreadsheet was used as a database for animal descriptions and other info. This information is loaded and shown in the game UI as necessary.
<br><br>
Another part was the webcam viewer for which it was necessary to display streams from Youtube and other sources. For this, VLC plugin was integrated.</p>', 'layers', '["Unity","VLC Player"]', '[{"label":"Platform","value":"PC"},{"label":"Type","value":"Museum Exhibit"}]', '[]', 0, 'published', 15);
