INSERT INTO projects (id, title, description, long_description, icon, tags, details, links, is_featured, status, position) VALUES ('find-yourself', 'Find Yourself in Europe', 'A digital board game for kids about Valmiera city, Europe and various professions.', '<p>A digital version of an already existing non-digital educational board game, made for Valmiera city library.
<br><br>
This is an educational board game with questions about Valmiera city, Europe and 10 different professions. The purpose is to educate children in a more engaging and interactive way.
<br><br>
The main goal of the game is to collect points by correctly answering to questions. The winner is who has the most points.</p>', 'map', '["Unity","C#","SQLite"]', '[{"label":"Platform","value":"PC"},{"label":"Type","value":"Educational Game"}]', '[]', 0, 'published', 16);
