INSERT INTO projects (id, title, description, long_description, icon, tags, details, links, is_featured, status, position) VALUES ('spatial', 'Spatial.io Custom Environments and Logic', 'A research project on Spatial.io and its capabilities.', '<p>This was a project within Vidzeme University of Applied Sciences for using VR technologies for immersive environments. In this case, main focus was on theatre and how Spatial can be used to help actors train for their plays remotely. Second focus was on how to use Spatial for group activities such as team-building work events.
<br><br>
Custom environments and logic was created using Spatial Creator Toolkit SDK for Unity.
<br><br>
Much of the project was exploring the SDK, creating various 3D environments, adding built-in Spatial functionalities, and also creating new logic with Visual Scripting specific for Spatial.</p>', 'users', '["Unity","VR","C#","Spatial.io SDK"]', '[{"label":"Platform","value":"VR & Flatscreen"},{"label":"Type","value":"Prototyping"}]', '[]', 0, 'published', 18);
